# which should have been included with this file.  If this file is
# file is missing or damaged, see the license at "http://www.cups.org/".
#

VERSION="2.2.13"
APIVERSION="2.2"
BUILD="cups-2.2.13"

prefix=/work
exec_prefix=/work
bindir=/work/bin
includedir=${prefix}/include
libdir=/out
imagelibdir=/out
datarootdir=/work/share
datadir=/work/share
sysconfdir=/work/etc
cups_datadir=/work/share/cups
cups_serverbin=/work/lib/cups
cups_serverroot=/work/etc/cups
INSTALLSTATIC=

# flags for C++ compiler:
CFLAGS=""
LDFLAGS="-Wl,-rpath,/out"
LIBS="  -lz -lpthread -lcrypt   -lz"

# Check for local invocation...
selfdir=`dirname $0`

if test -f "$selfdir/cups/cups.h"; then
    CFLAGS="-I$selfdir"
    LDFLAGS="-L$selfdir/cups -L$selfdir/filter $LDFLAGS"
    libdir="$selfdir/cups"
    imagelibdir="$selfdir/filter"
else
    if test $includedir != /usr/include; then
        CFLAGS="$CFLAGS -I$includedir"
    fi

    if test $libdir != /usr/lib -a $libdir != /usr/lib32 -a $libdir != /usr/lib64; then
        LDFLAGS="$LDFLAGS -L$libdir"
    fi
fi


usage ()
{
    echo "Usage: cups-config --api-version"
    echo "       cups-config --build"
    echo "       cups-config --cflags"
    echo "       cups-config --datadir"
    echo "       cups-config --help"
    echo "       cups-config --ldflags"
    echo "       cups-config [--image] [--static] --libs"
    echo "       cups-config --serverbin"
    echo "       cups-config --serverroot"
    echo "       cups-config --version"

    exit $1
}

if test $# -eq 0; then
    usage 1
fi

# Parse command line options
static=no
image=no

while test $# -gt 0; do
    case $1 in
        --api-version)
            echo $APIVERSION
            ;;
        --build)
            echo $BUILD
            ;;
        --cflags)
            echo $CFLAGS
            ;;
        --datadir)
            echo $cups_datadir
            ;;
        --help)
            usage 0
            ;;
        --image)
            image=yes
            ;;
        --ldflags)
            echo $LDFLAGS
            ;;
        --libs)
            if test $static = no; then
                libs="-lcups $LIBS";
                if test $image = yes; then
                    libs="-lcupsimage $libs"
                fi
            else
                libs="$libdir/libcups.a $LIBS";
                if test $image = yes; then
                    libs="$libdir/libcupsimage.a $libs"
                fi
            fi
            echo $libs
            ;;
        --serverbin)
            echo $cups_serverbin
            ;;
        --serverroot)
            echo $cups_serverroot
            ;;
        --static)
            if test -z "$INSTALLSTATIC"; then
                echo "WARNING: Static libraries not installed!" >&2
            else
                static=yes
            fi
            ;;
        --version)
            echo $VERSION
            ;;
        *)
            usage 1
            ;;
    esac

    shift
done
